// LOW. Native 0x142698da0: owner charge component; when WeaponState==3 and FX data valid, stop charge FX (0x1406d88f0).
// Then if owner is local or WeaponState==3, sets bit 0x40 in the flags word at +0x900 (name unresolved).
if (AFortPlayerController* OwnerController = Cast<AFortPlayerController>(GetOwner()))
{
    if (UObject* ChargeComponent = OwnerController->GetChargeComponentForWeapon())
    {
        if (WeaponState == 3 && IsValid(ChargeComponent))
        {
            StopChargeFX();   // 0x1406d88f0 (not named)
        }
    }
    if (OwnerController->IsLocalController() || WeaponState == 3)
    {
        ChargeFlags |= 0x40;   // +0x900, name unresolved
    }
}
